const cmd=String.raw`$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$doc = Join-Path $root 'docs/overview.md'
$text = Get-Content -Raw -LiteralPath $doc
$records = foreach ($match in [regex]::Matches($text, '\]\(([^)]+)\)')) {
  $target = $match.Groups[1].Value
  $resolved = [System.IO.Path]::GetFullPath((Join-Path (Split-Path $doc -Parent) $target))
  $inside = $resolved.StartsWith($root + [System.IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)
  $exists = Test-Path -LiteralPath $resolved -PathType Leaf
  "$target -> $resolved | inside=$inside exists=$exists"
  if (-not $inside -or -not $exists) { throw "Broken link: $target" }
}
$records | Set-Content -LiteralPath 'evidence/hg11-approve2/link-check.txt' -Encoding utf8
$records`;
const r=await tools.exec_command({cmd,workdir:"D:\\my_projects\\MyCodex\\target\\agent-pilot\\s7",max_output_tokens:1500});text(r);

