const cmd=String.raw`$ErrorActionPreference = 'Stop'
$before = @(git diff --cached --name-only)
if ($LASTEXITCODE -ne 0) { throw 'Could not read staged paths' }
if ($before.Count -ne 0 -and -not ($before.Count -eq 1 -and $before[0] -eq '')) { throw "Pre-existing staged changes: $before" }
git add -- docs/overview.md
if ($LASTEXITCODE -ne 0) { throw 'git add failed' }
git diff --cached --name-only > 'evidence/hg11-approve2/staged-paths.txt'
$paths = @(Get-Content -LiteralPath 'evidence/hg11-approve2/staged-paths.txt')
if ($paths.Count -ne 1 -or $paths[0] -ne 'docs/overview.md') { throw "Unexpected staged paths: $paths" }
git diff --cached -- docs/overview.md > 'evidence/hg11-approve2/staged.diff'
if ($LASTEXITCODE -ne 0) { throw 'Could not capture staged diff' }
git diff --cached --check > 'evidence/hg11-approve2/staged-diff-check.txt'
$checkExit = $LASTEXITCODE
$diff = Get-Content -Raw -LiteralPath 'evidence/hg11-approve2/staged.diff'
if ($checkExit -ne 0 -or $diff -notmatch 'Быстрая проверка поведения' -or $diff -match 'DEVELOPMENT-old\.md') { throw 'Staged diff did not match approved content' }
Write-Output "staged_paths=$($paths -join ',') diff_check_exit=$checkExit"
Get-Content -LiteralPath 'evidence/hg11-approve2/staged.diff'`;
const r=await tools.exec_command({cmd,workdir:"D:\\my_projects\\MyCodex\\target\\agent-pilot\\s7",max_output_tokens:1300});text(r);

const cmd=String.raw`$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$setup = Get-Content -Raw -LiteralPath 'evidence/hg11-approve2/setup.json' | ConvertFrom-Json
$work = Get-Content -Raw -LiteralPath 'evidence/hg11-approve2/work-snapshot.json' | ConvertFrom-Json
$head = (git rev-parse HEAD).Trim()
$parent = (git rev-parse HEAD^).Trim()
if ($LASTEXITCODE -ne 0 -or $parent -ne $setup.before_head) { throw 'Commit parent differs from setup HEAD' }
$paths = @(Get-Content -LiteralPath 'evidence/hg11-approve2/commit-paths.txt')
if ($paths.Count -ne 1 -or $paths[0] -ne 'docs/overview.md') { throw 'Commit includes an unexpected path' }
$stagedNow = @(git diff --cached --name-only)
if ($LASTEXITCODE -ne 0 -or ($stagedNow.Count -gt 0 -and $stagedNow[0] -ne '')) { throw 'Index not empty after commit' }
$after = [ordered]@{}
foreach ($entry in $work.work_sha256.PSObject.Properties) {
  $path = $entry.Name
  $hash = (Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $root ($path.Replace('/', '\')))).Hash.ToLowerInvariant()
  $after[$path] = $hash
  if ($hash -ne $entry.Value) { throw "File changed after work: $path" }
}
foreach ($entry in $setup.before_sha256.PSObject.Properties) {
  if ($entry.Name -ne 'docs/overview.md' -and $after[$entry.Name] -ne $entry.Value) {
    throw "Unrelated setup file changed: $($entry.Name)"
  }
}
$beforeStatus = @(Get-Content -LiteralPath 'evidence/hg11-approve2/before-status.txt' | Where-Object { $_ -notmatch 'docs/overview\.md$' })
$afterStatus = @(Get-Content -LiteralPath 'evidence/hg11-approve2/after-status.txt')
if (($beforeStatus -join "`n") -ne ($afterStatus -join "`n")) { throw 'Unrelated git status differs from setup' }
$manifest = [ordered]@{
  captured_at = [DateTime]::UtcNow.ToString('o')
  before_head = $setup.before_head
  work_head = $work.work_head
  after_head = $head
  commit_parent = $parent
  commit_paths = $paths
  before_sha256 = $setup.before_sha256
  work_sha256 = $work.work_sha256
  after_sha256 = $after
  work_to_after_unchanged = $true
  unrelated_status_preserved = $true
  staged_index_empty = $true
  activation = 'неприменима: по проектной инструкции нет установленного приложения или службы'
  publication = 'не выполнялась'
  user_acceptance = 'не запрашивалась и не объявлялась'
}
[System.IO.File]::WriteAllText((Join-Path $root 'evidence/hg11-approve2/after-snapshot.json'), ($manifest | ConvertTo-Json -Depth 8) + [Environment]::NewLine, (New-Object System.Text.UTF8Encoding($false)))
Write-Output "commit=$head parent=$parent paths=$($paths -join ',') unrelated_status_preserved=True"
Write-Output "overview_before=$($setup.before_sha256.'docs/overview.md')"
Write-Output "overview_work=$($work.work_sha256.'docs/overview.md')"
Write-Output "overview_after=$($after['docs/overview.md'])"`;
const r=await tools.exec_command({cmd,workdir:"D:\\my_projects\\MyCodex\\target\\agent-pilot\\s7",max_output_tokens:1000});text(r);

